#include <cstdio>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int x, y;
    scanf("%d %d", &x, &y);

    vector<int> sides(x, 3);
    int moves = 0;
    while (sides[2] != y) {
        sides[2] = max(sides[1] + 1 - sides[0], y);
        sort(sides.begin(), sides.end());
        moves += 1;
    }

    printf("%d\n", moves);

    return 0;
}

